import index from '../../data/problems/index.json';

/**
 * Practice problems with a judge: starter code, tests and expected outputs, generated by
 * problems/build.mjs into src/data/problems/<lessonId>.json. The small index ships with the app;
 * each lesson's file loads on demand.
 */
const files = import.meta.glob('../../data/problems/*.json', { import: 'default' });
const cache = new Map();

// index: { slug: lessonId }
export const hasProblem = (slug) => Boolean(index[slug]);
export const solvablePath = (slug) => `/solve/${slug}`;

export async function loadProblem(slug) {
  const lesson = index[slug];
  if (!lesson) return null;
  const path = `../../data/problems/${lesson}.json`;
  if (!cache.has(path)) cache.set(path, files[path]());
  const list = await cache.get(path);
  return list.find((p) => p.slug === slug) ?? null;
}

/** How many tests "Run" uses; "Submit" uses all of them. */
export const exampleCount = (spec) => Math.min(spec.examples ?? 2, spec.tests.length);
